public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    int required = pos + byteLength;
    if(required > buf.length){
        int newCap = Math.max(buf.length * 2, required);
        buf = java.util.Arrays.copyOf(buf, newCap);
    }
    if(byteArrayValue == null || byteLength == 0){
        java.util.Arrays.fill(buf, pos, pos + byteLength, (byte)0);
    }else{
        if(byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length){
            throw new IndexOutOfBoundsException("byteArrayValue[" + byteLength + " bytes from " + byteOffset + "]");
        }
        System.arraycopy(byteArrayValue, byteOffset, buf, pos, byteLength);
    }
    pos += byteLength;
    return this;
}

