final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    // Position after magic(4), minor(2), major(2)
    int offset = 8;
    // Read constant_pool_count
    int cpCount = classFileBuffer.getShort(offset) & 0xFFFF;
    offset += 2;
    int index = 1;
    // Walk through the constant pool to locate target entry
    while (index < constantPoolEntryIndex && index < cpCount) {
        byte tag = classFileBuffer.get(offset);
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int length = classFileBuffer.getShort(offset) & 0xFFFF;
                offset += 2 + length;
                break;
            case 3: // Integer
            case 4: // Float
            case 9: // Fieldref
            case 10: // Methodref
            case 11: // InterfaceMethodref
            case 12: // NameAndType
            case 18: // InvokeDynamic
                offset += 4;
                break;
            case 5: // Long
            case 6: // Double
                offset += 8;
                index++; // These take up two CP entries
                break;
            case 7: // Class
            case 8: // String
            case 16: // MethodHandle
            case 19: // Module
            case 20: // Package
                offset += 2;
                break;
            default:
                throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
        }
        index++;
    }
    if (index != constantPoolEntryIndex) {
        throw new IllegalArgumentException("Constant pool index out of bounds: " + constantPoolEntryIndex);
    }
    // Verify tag
    byte tag = classFileBuffer.get(offset);
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
    }
    offset++;
    int len = classFileBuffer.getShort(offset) & 0xFFFF;
    offset += 2;
    // Read the bytes using a duplicate buffer to avoid altering the original position
    java.nio.ByteBuffer dup = classFileBuffer.duplicate();
    dup.position(offset);
    byte[] utf8bytes = new byte[len];
    dup.get(utf8bytes);
    String result = new String(utf8bytes, java.nio.charset.StandardCharsets.UTF_8);
    // Copy into supplied buffer if it is large enough
    if (charBuffer.length >= len) {
        result.getChars(0, len, charBuffer, 0);
    }
    return result;
}

