private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> left = node.left;
    TreeNode<T> leftRight = left.right;

    // Perform rotation
    left.right = node;
    node.left = leftRight;

    // Update parents
    left.parent = node.parent;
    node.parent = left;
    if (leftRight != null) {
        leftRight.parent = node;
    }

    // If the rotated node had a parent, update the link from that parent to the new root
    if (left.parent != null) {
        if (left.parent.left == node) {
            left.parent.left = left;
        } else if (left.parent.right == node) {
            left.parent.right = left;
        }
    }

    return left;
}

