    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;
    if (prev != null) {
        prev.next = next;
    } else {
        head = next;
    }
    if (next != null) {
        next.prev = prev;
    } else {
        tail = prev;
    }
    node.prev = null;
    node.next = null;
    size--;
    return true;
}

