@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    // Add all vertices to the graph
    for (V vertex : resultMap.values()){
        target.addVertex(vertex);
    }
    // Build a simple bipartite partition: first half vs second half of the vertices list
    List<V> vertices = new ArrayList<>(resultMap.values());
    int partitionSize = vertices.size() / 2;
    for (int i = 0; i < partitionSize; i++){
        for (int j = partitionSize; j < vertices.size(); j++){
            target.addEdge(vertices.get(i), vertices.get(j));
        }
    }
}

