private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>(keys.size());
    List<Comparable> sorted = new ArrayList<>(keys.size());
    for (K key : keys){
        sorted.add((Comparable) key);
    }
    Collections.sort(sorted);
    for (K key : keys){
        int idx = Collections.binarySearch(sorted, (Comparable) key);
        if (idx < 0){
            idx = -idx - 1;
        }
        result.add(idx);
    }
    return result;
}

