private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    java.util.List<V> verts = new java.util.ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V v1 = verts.get(i);
        for (int j = i + 1; j < size; j++) {
            V v2 = verts.get(j);
            if (graph.getEdge(v1, v2) == null && graph.getEdge(v2, v1) == null) {
                return false;
            }
        }
    }
    return true;
}

