private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b0 = bb.get(i) & 0xFF;
    if (b0 < 0x80) {
        sb.append((char) b0);
        return i + 1;
    }
    int length;
    int codepoint;
    if ((b0 >> 5) == 0b110) { // two-byte sequence
        length = 2;
        int b1 = bb.get(i + 1) & 0x3F;
        codepoint = ((b0 & 0x1F) << 6) | b1;
    } else if ((b0 >> 4) == 0b1110) { // three-byte sequence
        length = 3;
        int b1 = bb.get(i + 1) & 0x3F;
        int b2 = bb.get(i + 2) & 0x3F;
        codepoint = ((b0 & 0x0F) << 12) | (b1 << 6) | b2;
    } else if ((b0 >> 3) == 0b11110) { // four-byte sequence
        length = 4;
        int b1 = bb.get(i + 1) & 0x3F;
        int b2 = bb.get(i + 2) & 0x3F;
        int b3 = bb.get(i + 3) & 0x3F;
        codepoint = ((b0 & 0x07) << 18) | (b1 << 12) | (b2 << 6) | b3;
    } else { // invalid UTF-8 byte
        sb.append('\uFFFD');
        return i + 1;
    }
    if (codepoint <= 0xFFFF) {
        sb.append((char) codepoint);
    } else {
        int cp = codepoint - 0x10000;
        sb.append((char) ((cp >> 10) + 0xD800));
        sb.append((char) ((cp & 0x03FF) + 0xDC00));
    }
    return i + length;
}

