    // Find the last dot
    int lastDot = path.lastIndexOf('.');
    // If no dot or dot comes before the last separator, no extension to strip
    if (lastDot <= lastSeparator) {
        return path;
    }
    // Strip the extension
    return path.substring(0, lastDot);
}

