protected int removeUnusedNodes(){
    int removedCount = 0;
    if (rootCategory == null) {
        return 0;
    }
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(rootCategory);
    while (!stack.isEmpty()) {
        Category node = stack.pop();
        List<Category> children = node.getChildCategories();
        if (children == null || children.isEmpty()) {
            continue;
        }
        Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove(); // detach from parent
                removedCount++;
            } else {
                stack.push(child);
            }
        }
    }
    return removedCount;
}

