private void pop(final String descriptor){
    // If the descriptor represents a method, pop each argument type from the output frame stack.
    if (descriptor.charAt(0) == '(') {
        int i = 1; // position after '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            // Determine the size of the next type descriptor.
            int typeLen = 1;
            char c = descriptor.charAt(i);
            if (c == '[') {                // array type
                // Skip all '[' characters
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                // Now i points at the element type; no additional length needed beyond the array brackets.
                typeLen = 1;                // element type will be parsed in the next iteration
            } else if (c == 'L') {           // reference type
                int semicolon = descriptor.indexOf(';', i);
                typeLen = semicolon - i + 1; // include the trailing ';'
            } // for primitive types, typeLen stays 1

            // Pop one value from the output frame stack.
            outputFrameStack.pop();

            // Advance i by the length of the type descriptor just processed.
            i += typeLen;
        }
    } else {
        // For a type descriptor (not a method), simply pop one value.
        outputFrameStack.pop();
    }
}

