public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Calculate serialized size using the provided schema
    int messageSize = schema.getSerializedSize(message);

    // Write the message size as a varint prefix to the output stream
    int size = messageSize;
    do {
        if ((size & ~0x7F) == 0) {
            out.write(size);
            break;
        } else {
            out.write((size & 0x7F) | 0x80);
            size >>>= 7;
        }
    } while (true);

    // Write the actual serialized message
    schema.writeTo(out, message);
    out.flush();
    return messageSize;
}

