public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    if (str == null) {
        return lb;
    }
    for (int i = 0; i < str.length(); ) {
        int cp = str.codePointAt(i);
        if (cp <= 0x7F) {
            lb.add((byte) cp);
        } else if (cp <= 0x7FF) {
            lb.add((byte) (0xC0 | (cp >> 6)));
            lb.add((byte) (0x80 | (cp & 0x3F)));
        } else if (cp <= 0xFFFF) {
            lb.add((byte) (0xE0 | (cp >> 12)));
            lb.add((byte) (0x80 | ((cp >> 6) & 0x3F)));
            lb.add((byte) (0x80 | (cp & 0x3F)));
        } else {
            // 4-byte UTF-8 sequence
            lb.add((byte) (0xF0 | (cp >> 18)));
            lb.add((byte) (0x80 | ((cp >> 12) & 0x3F)));
            lb.add((byte) (0x80 | ((cp >> 6) & 0x3F)));
            lb.add((byte) (0x80 | (cp & 0x3F)));
        }
        i += Character.charCount(cp);
    }
    return lb;
}

