public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    for (int i = 0; i < 10; i++) {
        int b = in.read();
        if (b == -1) throw new EOFException("Truncated Varint");
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Malformed varint");
}

