private void checkIfPackedField() throws IOException {
    // In protobuf wire format, a packed repeated field is encoded as a length-delimited field.
    // The current tag holds both field number and wire type. Wire type 2 indicates length-delimited.
    if ((currentTag & 0x7) == 2) {
        // Update internal state to remember that we are currently reading a packed field.
        // The field number can be retrieved by shifting the tag right by 3 bits.
        isReadingPackedField = true;
        packedFieldNumber = currentTag >>> 3;
    } else {
        isReadingPackedField = false;
        packedFieldNumber = -1;
    }
}

